# RW4DM_WHAT: What: the report of an object's kind, geometry and type. The script rw4dm_what_script.txt is generated by rw4dm_gen.py. The oracle is exact set / string logic on four objects (ids 1..4 = Point, Line, Plane, Box):
# after each step the objects that List reaches are compared, as id:kind:layer[:name], with the expected list exactly (and the printed message lines with their patterns).
RW4_WHAT_OUT=""
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RW4_WHAT_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rw4dm_what_script.txt" 2>&1)" || { echo "$RW4_WHAT_OUT" | tail -40; echo "FAIL RW4DM_WHAT_run: script exited non-zero"; fail=1; RW4_WHAT_OUT=""; }
else
  RW4_WHAT_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rw4dm_what_script.txt" 2>&1)" || { echo "$RW4_WHAT_OUT" | tail -40; echo "FAIL RW4DM_WHAT_run: script exited non-zero"; fail=1; RW4_WHAT_OUT=""; }
fi
rw4_what_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW4BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW4BEGIN_/ { exit } on { print }' <<<"$RW4_WHAT_OUT"; }
# rw4_what_state STEP EXPECTED DESC [PATTERN...]: the objects listed in the step read exactly EXPECTED ("-" = none); each PATTERN must match a printed line of the step
rw4_what_state() {
  local blk got name desc pat bad want; name="$1"; want="$2"; desc="$3"; blk="$(rw4_what_block "$name")"
  got="$({ grep -E '^history: Object [0-9]+ \(' <<<"$blk" || true; } | sed -E "s/^history: Object ([0-9]+) \(([^)]*)\) layer (.*) name '(.*)'\$/\1:\2:\3:\4/; s/^history: Object ([0-9]+) \(([^)]*)\) layer (.*)\$/\1:\2:\3/" | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  bad=""
  shift 3
  for pat in "$@"; do grep -qE "^history: $pat" <<<"$blk" || bad="$bad [$pat]"; done
  if [ "$got" = "$want" ] && [ -z "$bad" ]; then echo "ok   RW4DM_WHAT_$name: $desc (objects: $got)"
  else echo "FAIL RW4DM_WHAT_$name: $desc (listed '$got', expected '$want'; missing message patterns:${bad:- none})"; fail=1; { grep -E '^history: (Object|!|[A-Za-z]+:)' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}
rw4_what_state point "-" "What of a Point: kind, id, layer, location and bounding box" "point\$" "  ID: 1\$" "  Layer index: 0\$" "  Location: 1, 2, 3\$" "  Bounding box: \(1, 2, 3\) to \(1, 2, 3\)\$"
rw4_what_state line "-" "What of the 3-4-5 line: degree 1, 2 control points, length 5, type Line with its end points" "curve\$" "  ID: 2\$" "  Degree: 1\$" "  Control points: 2\$" "  Closed: no\$" "  Length: 5\$" "  Type: Line, from \(0, 0, 0\) to \(3, 4, 0\), length 5\$" "  Bounding box: \(0, 0, 0\) to \(3, 4, 0\)\$"
rw4_what_state circle "-" "What of a circle of radius 2 about (5,5,0): closed, type Circle with its centre, radius and normal" "curve\$" "  Closed: yes\$" "  Type: Circle, center \(5, 5, 0\), radius 2, normal \(0, 0, 1\)\$"
rw4_what_state sphere "-" "What of a sphere of radius 3: one face of type Sphere with its centre and radius" "polysurface\$" "  Faces: 1\$" "  Face types: Sphere x1\$" "  Face 0: Sphere, center \(0, 0, 0\), radius 3\$"
rw4_what_state box "-" "What of the 2 x 3 x 4 box: 6 faces, all planes, bounding box (10,0,0) to (12,3,4)" "polysurface\$" "  Faces: 6\$" "  Face types: Plane x6\$" "  Bounding box: \(10, 0, 0\) to \(12, 3, 4\)\$"
rw4_what_state cylinder "-" "What of a cylinder of radius 2 and height 5: 3 faces, two planes and one cylinder of radius 2 about the vertical axis through (20,0)" "polysurface\$" "  Faces: 3\$" "  Face types: Plane x2, Cylinder x1\$" "  Face [0-9]+: Cylinder, radius 2, axis \(0, 0, -?1\) through \(20, 0, [0-9]+\)$"
